#if 1
static void commit_write_sensor(struct subdrv_ctx *ctx)
{
	if (_size_to_write) {
		s5khp2sx_table_write_cmos_sensor_16(ctx, _i2c_data, _size_to_write);
		memset(_i2c_data, 0x0, sizeof(_i2c_data));
		_size_to_write = 0;
	}
}

static void set_cmos_sensor_16(struct subdrv_ctx *ctx,kal_uint16 reg, kal_uint16 val)
{
	if (_size_to_write + 2 >= _I2C_BUF_SIZE)
		commit_write_sensor(ctx);

	_i2c_data[_size_to_write++] = reg;
	_i2c_data[_size_to_write++] = val;
}
#endif


