static void set_dummy(struct subdrv_ctx *ctx)
{
	LOG_INF("dummyline = %d, dummypixels = %d\n",	ctx->dummy_line, ctx->dummy_pixel);
	set_cmos_sensor_16(ctx, 0x0340, ctx->frame_length);
	set_cmos_sensor_16(ctx, 0x0342, ctx->line_length);

	commit_write_sensor(ctx);
}	/*	set_dummy  */


static void set_max_framerate(struct subdrv_ctx *ctx, UINT16 framerate,
	kal_bool min_framelength_en)
{
	kal_uint32 frame_length = ctx->frame_length;

	LOG_INF("framerate = %d, min framelength should enable %d\n",framerate, min_framelength_en);

	frame_length = ctx->pclk / framerate * 10 / ctx->line_length;
	if (frame_length >= ctx->min_frame_length)
		ctx->frame_length = frame_length;
	else
		ctx->frame_length = ctx->min_frame_length;

	ctx->dummy_line =
		ctx->frame_length - ctx->min_frame_length;

	if (ctx->frame_length > imgsensor_info.max_frame_length) {
		ctx->frame_length = imgsensor_info.max_frame_length;
		ctx->dummy_line = ctx->frame_length - ctx->min_frame_length;
	}
	if (min_framelength_en)
		ctx->min_frame_length = ctx->frame_length;
}	/*	set_max_framerate  */


static void write_shutter(struct subdrv_ctx *ctx,kal_uint32 shutter)
{
	kal_uint16 realtime_fps = 0;

	if(shutter >= 96200)
	{
		/*enter long exposure mode */
		kal_uint32 exposure_time;
		kal_uint16 new_framelength;
		kal_uint16 long_shutter=0;

		bIsLongExposure = KAL_TRUE;
		exposure_time = shutter*ctx->line_length/1599000;
		long_shutter = shutter / 128 ;
		//LOG_INF("enter long exposure mode long_shutter = %d, long_exposure_time =%ld ms\n", long_shutter, exposure_time);
		new_framelength = long_shutter + 24;

		set_cmos_sensor_16(ctx,0x0340, new_framelength);
		set_cmos_sensor_16(ctx,0x0202, long_shutter);
		set_cmos_sensor_16(ctx,0x0702, 0x0700);
		set_cmos_sensor_16(ctx,0x0704, 0x0700);

		ctx->ae_frm_mode.frame_mode_1 = IMGSENSOR_AE_MODE_SE;
		ctx->ae_frm_mode.frame_mode_2 = IMGSENSOR_AE_MODE_SE;
		ctx->current_ae_effective_frame = 2;
	}
	else
	{
		ctx->current_ae_effective_frame = 2;
		if (bIsLongExposure)
		{
			LOG_INF("enter normal shutter.\n");
			set_cmos_sensor_16(ctx,0x6028, 0x4000);
			set_cmos_sensor_16(ctx,0x0340, ctx->frame_length);
			set_cmos_sensor_16(ctx,0x0702, 0x0000);
			set_cmos_sensor_16(ctx,0x0704, 0x0000);
			set_cmos_sensor_16(ctx,0x0202, shutter);
			bIsLongExposure = KAL_FALSE;
		}

		spin_lock(&imgsensor_drv_lock);
		if (shutter > ctx->min_frame_length - imgsensor_info.margin)
			ctx->frame_length = shutter + imgsensor_info.margin;
		//else
		//	ctx->frame_length = ctx->min_frame_length;
		if (ctx->frame_length > imgsensor_info.max_frame_length)
			ctx->frame_length = imgsensor_info.max_frame_length;
		spin_unlock(&imgsensor_drv_lock);

		if (shutter < imgsensor_info.min_shutter)
			shutter = imgsensor_info.min_shutter;

		if (ctx->autoflicker_en)
		{
			realtime_fps = ctx->pclk / ctx->line_length * 10 / ctx->frame_length;
			if(realtime_fps >= 297 && realtime_fps <= 305)
				set_max_framerate(ctx,296,0);
			else if(realtime_fps >= 147 && realtime_fps <= 150)
				set_max_framerate(ctx,146,0);
			else
				/* Extend frame length*/
				set_cmos_sensor_16(ctx,0x0340, ctx->frame_length);
		}
		else
		{
			/* Extend frame length*/
			set_cmos_sensor_16(ctx,0x0340, ctx->frame_length);
		}

		/* Update Shutter*/
		//agold chenpeng change for its test_raw_exposure
		if(shutter >=  0xFF7F)
			shutter = 0xFF7F;
		set_cmos_sensor_16(ctx,0x0202, shutter);
	}
	commit_write_sensor(ctx);
	LOG_INF("Exit! shutter =%d, framelength =%d\n", shutter, ctx->frame_length);
}


/*************************************************************************
 * FUNCTION
 *	set_shutter
 *
 * DESCRIPTION
 *	This function set e-shutter of sensor to change exposure time.
 *
 * PARAMETERS
 *	iShutter : exposured lines
 *
 * RETURNS
 *	None
 *
 * GLOBALS AFFECTED
 *
 *************************************************************************/
static void set_shutter(struct subdrv_ctx *ctx,kal_uint32 shutter)
{
	unsigned long flags;

	spin_lock_irqsave(&imgsensor_drv_lock, flags);
	ctx->shutter = shutter;
	spin_unlock_irqrestore(&imgsensor_drv_lock, flags);
	write_shutter(ctx,shutter);
}				/*      set_shutter */

static void set_frame_length(struct subdrv_ctx *ctx, kal_uint16 frame_length)
{
	if (frame_length > 1)
		ctx->frame_length = frame_length;

	if (ctx->frame_length > imgsensor_info.max_frame_length)
		ctx->frame_length = imgsensor_info.max_frame_length;
	if (ctx->min_frame_length > ctx->frame_length)
		ctx->frame_length = ctx->min_frame_length;

	/* Extend frame length */
	write_cmos_sensor_16(ctx, 0x0340, ctx->frame_length & 0xFFFF);

	LOG_INF("Framelength: set=%d/input=%d/min=%d\n",
		ctx->frame_length, frame_length, ctx->min_frame_length);
}
static void set_multi_shutter_frame_length(struct subdrv_ctx *ctx,
				kal_uint32 *shutters, kal_uint16 shutter_cnt,
				kal_uint16 frame_length)
{
	if (shutter_cnt == 1) {
		ctx->shutter = shutters[0];

		if (shutters[0] > ctx->min_frame_length - imgsensor_info.margin)
			ctx->frame_length = shutters[0] + imgsensor_info.margin;
		else
			ctx->frame_length = ctx->min_frame_length;

		if (frame_length > ctx->frame_length)
			ctx->frame_length = frame_length;
		if (ctx->frame_length > imgsensor_info.max_frame_length)
			ctx->frame_length = imgsensor_info.max_frame_length;

		if (shutters[0] < imgsensor_info.min_shutter)
			shutters[0] = imgsensor_info.min_shutter;

		/* Update Shutter */
		write_cmos_sensor_8(ctx, 0x0104, 0x01);//grouphold start
		write_cmos_sensor_16(ctx, 0x0340, ctx->frame_length & 0xFFFF);
		write_cmos_sensor_16(ctx, 0X0202, shutters[0] & 0xFFFF);
		if (!ctx->ae_ctrl_gph_en)
			write_cmos_sensor_8(ctx, 0x0104, 0x00);//grouphold end
		commit_write_sensor(ctx);
LOG_INF("shutters[0] =%d, framelength =%d\n",
			shutters[0], ctx->frame_length);
		DEBUG_LOG(ctx, "shutters[0] =%d, framelength =%d\n",
			shutters[0], ctx->frame_length);
	}
}
/*************************************************************************
 * FUNCTION
 *	set_shutter_frame_length
 *
 * DESCRIPTION
 *	for frame & 3A sync
 *
 *************************************************************************/
static void set_shutter_frame_length(struct subdrv_ctx *ctx,
	kal_uint16 shutter, kal_uint16 frame_length,kal_bool auto_extend_en)
{
	unsigned long flags;
	kal_uint16 realtime_fps = 0;
	//kal_uint32 frame_length = 0;
	spin_lock_irqsave(&imgsensor_drv_lock, flags);
	ctx->shutter = shutter;
	spin_unlock_irqrestore(&imgsensor_drv_lock, flags);

	//write_shutter(ctx,shutter);
	/* 0x3500, 0x3501, 0x3502 will increase VBLANK to get exposure larger than frame exposure */
	/* AE doesn't update sensor gain at capture mode, thus extra exposure lines must be updated here. */

	// if shutter bigger than frame_length, should extend frame length first
	spin_lock(&imgsensor_drv_lock);
	if (shutter > ctx->min_frame_length - imgsensor_info.margin)
		ctx->frame_length = shutter + imgsensor_info.margin;
	else
		ctx->frame_length = ctx->min_frame_length;
	if (ctx->frame_length > imgsensor_info.max_frame_length)
		ctx->frame_length = imgsensor_info.max_frame_length;
	spin_unlock(&imgsensor_drv_lock);
	shutter = (shutter < imgsensor_info.min_shutter) ? imgsensor_info.min_shutter : shutter;
	shutter = (shutter > (imgsensor_info.max_frame_length - imgsensor_info.margin)) ? (imgsensor_info.max_frame_length - imgsensor_info.margin) : shutter;

	if (ctx->autoflicker_en) {
		realtime_fps = ctx->pclk / ctx->line_length * 10 / ctx->frame_length;
		if (realtime_fps >= 297 && realtime_fps <= 305)
			set_max_framerate(ctx,296, 0);
		else if (realtime_fps >= 147 && realtime_fps <= 150)
			set_max_framerate(ctx,146, 0);
		else {
		// Extend frame length
		set_cmos_sensor_16(ctx,0x0340, ctx->frame_length & 0xFFFF);
		}
	} else {
		// Extend frame length
		set_cmos_sensor_16(ctx,0x0340, ctx->frame_length & 0xFFFF);
	}

	// Update Shutter
	set_cmos_sensor_16(ctx,0x0202, shutter & 0xFFFF);
	commit_write_sensor(ctx);
	LOG_INF("Exit! shutter =%d, framelength =%d\n", shutter, ctx->frame_length);

}	/* set_shutter_frame_length */


static kal_uint16 gain2reg(struct subdrv_ctx *ctx, const kal_uint32 gain)
{
	kal_uint16 reg_gain = 0x0;
	//gain = 64 = 1x real gain.
	//reg_gain = gain / 2;
	reg_gain = gain * 32 / BASEGAIN;
	
	return (kal_uint16)reg_gain;
}


/*************************************************************************
* FUNCTION
*	set_gain
*
* DESCRIPTION
*	This function is to set global gain to sensor.
*
* PARAMETERS
*	iGain : sensor global gain(base: 0x40)
*
* RETURNS
*	the actually gain set to sensor.
*
* GLOBALS AFFECTED
*
*************************************************************************/
//static kal_uint16 set_gain(kal_uint16 gain)
static kal_uint32 set_gain(struct subdrv_ctx *ctx, kal_uint32 gain)
{

	//gain = 64 = 1x real gain.
	kal_uint16 reg_gain;
	LOG_INF("set_gain %d\n", gain);
	if (gain < BASEGAIN || gain > 32 * BASEGAIN)
	{
		LOG_INF("Error gain setting");
		if (gain < BASEGAIN)
			gain = BASEGAIN;
		else if (gain > 32 * BASEGAIN)
			gain = 32 * BASEGAIN;
	}

	reg_gain = gain2reg(ctx,gain);
	spin_lock(&imgsensor_drv_lock);
	ctx->gain = reg_gain;
	spin_unlock(&imgsensor_drv_lock);
	LOG_INF("gain = %d , reg_gain = %d(%x) \n ", gain, reg_gain, reg_gain);

	set_cmos_sensor_16(ctx,0x0204, (reg_gain & 0xFFFF));
	if (ctx->ae_ctrl_gph_en)
		set_cmos_sensor_16(ctx, 0x0104, 0x00); //grouphold end
	commit_write_sensor(ctx);
	return gain;
} /*	set_gain  */

