//static void set_mirror_flip(kal_uint8 image_mirror)
static void set_mirror_flip(struct subdrv_ctx *ctx, kal_uint8 image_mirror)
{
	LOG_INF("image_mirror = %d\n", image_mirror);

	/********************************************************
	   *
	   *   0x3820[2] ISP Vertical flip
	   *   0x3820[1] Sensor Vertical flip
	   *
	   *   0x3821[2] ISP Horizontal mirror
	   *   0x3821[1] Sensor Horizontal mirror
	   *
	   *   ISP and Sensor flip or mirror register bit should be the same!!
	   *
	   ********************************************************/
	spin_lock(&imgsensor_drv_lock);
	//image_mirror &= 3;
	ctx->mirror = image_mirror;
	spin_unlock(&imgsensor_drv_lock);
	switch (image_mirror)
	{
	case IMAGE_NORMAL:
		write_cmos_sensor_8(ctx, 0x0101, 0x00); //GR
		break;
	case IMAGE_H_MIRROR:
		write_cmos_sensor_8(ctx, 0x0101, 0x01); //R
		break;
	case IMAGE_V_MIRROR:
		write_cmos_sensor_8(ctx, 0x0101, 0x02); //B
		break;
	case IMAGE_HV_MIRROR:
		write_cmos_sensor_8(ctx, 0x0101, 0x03); //GB
		break;
	default:
		LOG_INF("Error image_mirror setting\n");
	}
}

/*************************************************************************
* FUNCTION
*	night_mode
*
* DESCRIPTION
*	This function night mode of sensor.
*
* PARAMETERS
*	bEnable: KAL_TRUE -> enable night mode, otherwise, disable night mode
*
* RETURNS
*	None
*
* GLOBALS AFFECTED
*
*************************************************************************/

//static kal_uint32 streaming_control(kal_bool enable)
static kal_uint32 streaming_control(struct subdrv_ctx *ctx, kal_bool enable)
{
	//write_cmos_sensor_byte

	int i = 0;
	int framecnt = 0;
	int isStreamOn = 0;

	LOG_INF("streaming_enable(0=Sw Standby,1=streaming): %d\n", enable);
	if (enable)
	{
		// while (1)
		for (i = 0; i < 1000; i++)
		{
			write_cmos_sensor_8(ctx, 0x0100, 0x01);
			isStreamOn = read_cmos_sensor_8(ctx,0x0100); /* waiting for sensor to  stop output  then  set the  setting */
			LOG_INF("i=%d,isStreamOn %d ",i, isStreamOn);

			if ((isStreamOn & 0x1) == 0x01)
			{
				return ERROR_NONE;
			}
			else
			{
				mdelay(1);
			}
		}
	}
	else
	{

		//while(1) {
		for (i = 0; i < 30; i++)
		{
			write_cmos_sensor_8(ctx, 0x0100, 0x00);
			framecnt = read_cmos_sensor_8(ctx,0x0005);
			if ((framecnt & 0xff) == 0xFF)
			{
				LOG_INF("StreamOff i=%d OK at framecnt=%d.\n", i,framecnt);
				break;
			}
			else
			{
				LOG_INF("StreamOFF is not on, %d, i=%d", framecnt, i);
				mdelay(1);
			}
		}
	}
	return ERROR_NONE;
}

